import sys

class BankAccount:
    def __init__(self, principal):
        self.__principal = principal

    def calculate_interest(self, rate, time):
        return (self.__principal * rate * time) / 100

def main():
    line = sys.stdin.readline()
    if not line:
        return
    parts = line.strip().split()
    if len(parts) < 3:
        return
    try:
        principal = float(parts[0])
        rate = float(parts[1])
        time = float(parts[2])
    except ValueError:
        return

    account = BankAccount(principal)
    interest = account.calculate_interest(rate, time)
    result = int(interest) if interest == int(interest) else interest
    print(result)

if __name__ == "__main__":
    main()
